begin;
do $$declare role_name text;begin foreach role_name in array array['auth_role','maintenance_role','knowledge_role','knowledge_reviewer_role']loop if not exists(select from pg_roles where rolname=role_name)then execute format('create role %I nologin noinherit nosuperuser nocreatedb nocreaterole noreplication nobypassrls',role_name);end if;end loop;end$$;
grant usage on schema public to maintenance_role,knowledge_role,knowledge_reviewer_role;
create table public.retention_objects(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),kind text not null check(kind in('recording','transcript','trace')),source_reference text not null,payload_hash text not null check(payload_hash~'^[a-f0-9]{64}$'),byte_length bigint not null check(byte_length>=0),voice_session_id uuid references public.voice_sessions(id),created_at timestamptz not null default clock_timestamp(),expires_at timestamptz not null default(clock_timestamp()+interval'90 days'),unique(mission_id,id),unique(mission_id,source_reference));
create table private.retention_payloads(object_id uuid primary key references public.retention_objects(id)on delete cascade,payload jsonb not null);
create table public.retention_choices(id uuid primary key default gen_random_uuid(),mission_id uuid not null,object_id uuid not null,keep boolean not null,actor_id uuid not null,created_at timestamptz not null default clock_timestamp(),foreign key(mission_id,object_id)references public.retention_objects(mission_id,id));
create table public.retention_purges(id uuid primary key default gen_random_uuid(),mission_id uuid not null,object_id uuid not null unique,reason text not null check(reason in('expired','trace_opt_out')),created_at timestamptz not null default clock_timestamp(),foreign key(mission_id,object_id)references public.retention_objects(mission_id,id));
create table private.maintenance_audit(id uuid primary key default gen_random_uuid(),operation text not null,object_count bigint not null,stream_count bigint not null,dry_run boolean not null,created_at timestamptz not null default clock_timestamp());
do $$declare table_name text;begin foreach table_name in array array['retention_objects','retention_choices','retention_purges']loop execute format('alter table public.%I enable row level security',table_name);execute format('alter table public.%I force row level security',table_name);execute format('create policy mission_scope on public.%I using(private.owns_mission(mission_id))with check(private.owns_mission(mission_id))',table_name);execute format('create trigger immutable_row before update or delete on public.%I for each row execute function private.immutable_row()',table_name);execute format('create trigger ledger_revision after insert on public.%I for each row execute function private.record_ledger_revision()',table_name);execute format('grant select on public.%I to founder_role,lead_role,policy_role',table_name);end loop;end$$;
create function public.configure_trace_retention(p_mission uuid,p_enabled boolean)returns void language plpgsql security definer set search_path=''as $$begin perform private.require_role(array['founder_role']);perform private.lock_mission(p_mission);if p_enabled is null then raise exception 'validation: explicit tracing preference required';end if;insert into public.founder_preferences(mission_id,kind,value,actor_id)values(p_mission,'trace_retention',jsonb_build_object('enabled',p_enabled),private.actor_id());end$$;
create function public.trace_export_allowed(p_mission uuid)returns boolean language plpgsql stable security definer set search_path=''as $$begin perform private.require_role(array['policy_role','founder_role']);perform private.assert_mission(p_mission);return coalesce((select(value->>'enabled')::boolean from public.founder_preferences where mission_id=p_mission and kind='trace_retention'order by created_at desc,id desc limit 1),true);end$$;
create function public.keep_retained_content(p_mission uuid,p_object uuid,p_keep boolean)returns void language plpgsql security definer set search_path=''as $$begin
 perform private.require_role(array['founder_role']);perform private.lock_mission(p_mission);if p_keep is null or not exists(select from public.retention_objects where mission_id=p_mission and id=p_object and(not p_keep or kind in('recording','transcript')))then raise exception 'validation: scoped retained object required';end if;if p_keep and not exists(select from private.retention_payloads where object_id=p_object)then raise exception 'conflict: expired content cannot be recovered by a keep preference';end if;insert into public.retention_choices(mission_id,object_id,keep,actor_id)values(p_mission,p_object,p_keep,private.actor_id());
end$$;
create function public.store_retained_content(p_mission uuid,p_kind text,p_source text,p_payload jsonb,p_session uuid default null,p_redacted boolean default false)returns uuid language plpgsql security definer set search_path=''as $$declare object uuid;digest text;begin
 perform private.require_role(array['policy_role','voice_role','ingress_role']);perform private.lock_mission(p_mission);perform private.assert_safe_content(p_payload);
 if p_kind not in('recording','transcript','trace')or coalesce(p_source,'')!~'^[A-Za-z0-9_.:-]{1,160}$' or p_payload is null or octet_length(p_payload::text)>5000000 then raise exception 'validation: bounded retained raw content required';end if;
 if p_kind='trace'then if private.caller_role()<>'policy_role'or p_redacted is distinct from true then raise exception 'invariant_violation: only explicitly redacted policy traces may be retained';end if;if not public.trace_export_allowed(p_mission)then return null;end if;
 elsif not exists(select from public.voice_sessions where mission_id=p_mission and id=p_session and recording_consent)then raise exception 'invariant_violation: recorded session consent required';end if;
 digest:=encode(public.digest(p_payload::text,'sha256'),'hex');select id into object from public.retention_objects where mission_id=p_mission and source_reference=p_source;if object is not null then if not exists(select from public.retention_objects where id=object and kind=p_kind and payload_hash=digest and voice_session_id is not distinct from p_session)then raise exception 'invariant_violation: retained source content changed';end if;return object;end if;
 insert into public.retention_objects(mission_id,kind,source_reference,payload_hash,byte_length,voice_session_id)values(p_mission,p_kind,p_source,digest,octet_length(p_payload::text),p_session)returning id into object;insert into private.retention_payloads(object_id,payload)values(object,p_payload);return object;
end$$;
create function public.read_retained_content(p_mission uuid,p_object uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$begin
 perform private.require_role(array['founder_role']);perform private.assert_mission(p_mission);
 return(select p.payload from private.retention_payloads p join public.retention_objects o on o.id=p.object_id
 where o.mission_id=p_mission and o.id=p_object
 and(o.expires_at>clock_timestamp()or coalesce((select choice.keep from public.retention_choices choice where choice.object_id=o.id order by choice.created_at desc,choice.id desc limit 1),false))
 and(o.kind<>'trace'or public.trace_export_allowed(p_mission)));
end$$;
-- Raw recording/transcript payloads are never placed in the immutable event
-- ledger from this migration onward. Existing business facts remain unchanged.
create function private.retain_voice_raw_payload()returns trigger language plpgsql security definer set search_path=''as $$declare object uuid;hash text;begin
 if new.kind in('recording','transcript')then object:=public.store_retained_content(new.mission_id,new.kind,'voice-event:'||encode(public.digest(new.session_id::text||':'||new.event_key,'sha256'),'hex'),new.payload,new.session_id,false);select payload_hash into hash from public.retention_objects where id=object;new.payload:=jsonb_build_object('retentionObjectId',object,'payloadHash',hash,'recordingConsent',true,'rawKind',new.kind)||case when new.kind='recording'then jsonb_strip_nulls(jsonb_build_object('recordingSid',case when new.payload->>'recordingSid'~'^RE[a-fA-F0-9]{32}$'then new.payload->>'recordingSid'end,'callSid',case when new.payload->>'callSid'~'^CA[a-fA-F0-9]{32}$'then new.payload->>'callSid'end))else'{}'::jsonb end;end if;return new;
end$$;
create trigger retain_voice_raw_payload before insert on public.voice_session_events for each row execute function private.retain_voice_raw_payload();
create function public.expire_retained_content(p_dry_run boolean default true)returns jsonb language plpgsql security definer set search_path=''as $$declare item record;objects bigint:=0;streams bigint:=0;begin
 perform private.require_role(array['maintenance_role']);if p_dry_run is null then raise exception 'validation: explicit dry-run flag required';end if;perform pg_advisory_xact_lock(407040);
 for item in select o.*,case when o.kind='trace'and coalesce((select(value->>'enabled')::boolean from public.founder_preferences where mission_id=o.mission_id and kind='trace_retention'order by created_at desc,id desc limit 1),true)=false then'trace_opt_out'else'expired'end reason from public.retention_objects o join private.retention_payloads payload on payload.object_id=o.id where(o.expires_at<=clock_timestamp()or(o.kind='trace'and coalesce((select(value->>'enabled')::boolean from public.founder_preferences where mission_id=o.mission_id and kind='trace_retention'order by created_at desc,id desc limit 1),true)=false))and coalesce((select keep from public.retention_choices where object_id=o.id order by created_at desc,id desc limit 1),false)=false order by o.expires_at,o.id limit 1000 loop
  -- Serialize with founder keep/opt-out decisions and recheck after acquiring
  -- the mission lock. No application-controlled clock or retention period.
  perform 1 from public.missions where id=item.mission_id for update;
  if coalesce((select keep from public.retention_choices where object_id=item.id order by created_at desc,id desc limit 1),false)then continue;end if;if item.expires_at>clock_timestamp()and(item.kind<>'trace'or coalesce((select(value->>'enabled')::boolean from public.founder_preferences where mission_id=item.mission_id and kind='trace_retention'order by created_at desc,id desc limit 1),true))then continue;end if;objects:=objects+1;if not p_dry_run then delete from private.retention_payloads where object_id=item.id;insert into public.retention_purges(mission_id,object_id,reason)values(item.mission_id,item.id,item.reason)on conflict(object_id)do nothing;end if;
 end loop;
 select count(*)into streams from public.agent_message_streams where expires_at<=clock_timestamp();if not p_dry_run then delete from public.agent_message_streams where expires_at<=clock_timestamp();end if;insert into private.maintenance_audit(operation,object_count,stream_count,dry_run)values('expire_retained_content',objects,streams,p_dry_run);return jsonb_build_object('dryRun',p_dry_run,'rawObjects',objects,'ephemeralStreams',streams,'businessLedgerRowsDeleted',0);
end$$;
revoke all on function private.retain_voice_raw_payload()from public;
revoke all on function public.configure_trace_retention(uuid,boolean),public.trace_export_allowed(uuid),public.keep_retained_content(uuid,uuid,boolean),public.store_retained_content(uuid,text,text,jsonb,uuid,boolean),public.read_retained_content(uuid,uuid),public.expire_retained_content(boolean)from public;
grant execute on function public.configure_trace_retention(uuid,boolean),public.keep_retained_content(uuid,uuid,boolean),public.read_retained_content(uuid,uuid)to founder_role;
grant execute on function public.trace_export_allowed(uuid)to founder_role,policy_role;
grant execute on function public.store_retained_content(uuid,text,text,jsonb,uuid,boolean)to policy_role,voice_role,ingress_role;
grant execute on function public.expire_retained_content(boolean)to maintenance_role;
create table private.knowledge_reviewers(login_role name primary key,reviewer_reference text not null,enabled boolean not null default true);
create table public.knowledge_revisions(id uuid primary key default gen_random_uuid(),kind text not null check(kind in('category_profile','playbook','template','readiness_rules')),knowledge_id text not null,version integer not null check(version>0),content_hash text not null,source_hash text not null,sources text[] not null,review_status text not null check(review_status in('unverified','reviewed')),reviewer_reference text,review_reference text,reviewed_at timestamptz,created_at timestamptz not null default clock_timestamp(),unique(kind,knowledge_id,version));
create table public.knowledge_pointers(id uuid primary key default gen_random_uuid(),kind text not null,knowledge_id text not null,version integer not null,reviewer_reference text not null,created_at timestamptz not null default clock_timestamp(),foreign key(kind,knowledge_id,version)references public.knowledge_revisions(kind,knowledge_id,version));
create trigger immutable_row before update or delete on public.knowledge_revisions for each row execute function private.immutable_row();create trigger immutable_row before update or delete on public.knowledge_pointers for each row execute function private.immutable_row();
revoke all on public.knowledge_revisions,public.knowledge_pointers from public;grant select on public.knowledge_revisions,public.knowledge_pointers to founder_role,lead_role,specialist_role,policy_role,knowledge_role,knowledge_reviewer_role;
create function public.knowledge_payload_hashes(p_content jsonb,p_sources text[])returns jsonb language plpgsql stable security definer set search_path=''as $$begin perform private.require_role(array['knowledge_role','knowledge_reviewer_role']);if p_content is null or octet_length(p_content::text)>1000000 or p_sources is null or cardinality(p_sources)>50 then raise exception 'validation: bounded knowledge payload required';end if;return jsonb_build_object('contentHash',encode(public.digest(p_content::text,'sha256'),'hex'),'sourceHash',encode(public.digest(to_jsonb(p_sources)::text,'sha256'),'hex'));end$$;
revoke all on function public.knowledge_payload_hashes(jsonb,text[])from public;grant execute on function public.knowledge_payload_hashes(jsonb,text[])to knowledge_role,knowledge_reviewer_role;
create function public.append_knowledge_revision(p_kind text,p_id text,p_version integer,p_content jsonb,p_sources text[],p_review jsonb default null)returns uuid language plpgsql security definer set search_path=''as $$
declare hash text;source_hash text;reviewer text;status text:='unverified';review_at timestamptz;previous integer;result uuid;rule jsonb;begin
 perform private.require_role(array['knowledge_role','knowledge_reviewer_role']);perform private.assert_safe_content(p_content);perform pg_advisory_xact_lock(hashtextextended('knowledge:'||p_kind||':'||p_id,0));
 if p_kind not in('category_profile','playbook','template','readiness_rules')or p_id!~'^[a-z0-9][a-z0-9_.:-]{0,119}$'or p_version is null or p_version<=0 or jsonb_typeof(p_content)is distinct from'object'or octet_length(p_content::text)>1000000 or p_sources is null or cardinality(p_sources)not between 1 and 50 or exists(select from unnest(p_sources)source where source is null or source!~'^(repo:docs/[^?]*|https://[^/@?#]+(/[^?]*)?)$')then raise exception 'validation: versioned knowledge content and explicit source provenance required';end if;
 hash:=encode(public.digest(p_content::text,'sha256'),'hex');source_hash:=encode(public.digest(to_jsonb(p_sources)::text,'sha256'),'hex');
 if p_review is not null then
  if private.caller_role()<>'knowledge_reviewer_role'or not exists(select from private.knowledge_reviewers where login_role=session_user and enabled)then raise exception 'invariant_violation: registered human reviewer login required';end if;select reviewer_reference into reviewer from private.knowledge_reviewers where login_role=session_user and enabled;
  if jsonb_typeof(p_review)is distinct from'object'or not(p_review?&array['contentHash','sourceHash','reviewReference','reviewedAt','attestation'])or p_review-array['contentHash','sourceHash','reviewReference','reviewedAt','attestation']<>'{}'::jsonb or p_review->>'contentHash'is distinct from hash or p_review->>'sourceHash'is distinct from source_hash or coalesce(p_review->>'reviewReference','')!~'^(repo:docs/[^?]*|https://[^/@?#]+(/[^?]*)?)$'or p_review->>'attestation'is distinct from'I personally reviewed this exact content and sources'then raise exception 'validation: exact dated human review provenance required';end if;
  review_at:=private.readiness_date(p_review->>'reviewedAt');if review_at is null or review_at>clock_timestamp()or review_at<clock_timestamp()-interval'30 days'then raise exception 'validation: current dated human review required';end if;status:='reviewed';
 end if;
 if p_kind='category_profile'then select max(version)into previous from public.category_profiles where id=p_id;
 elsif p_kind='playbook'then select max(version)into previous from public.playbooks where id=p_id;
 elsif p_kind='template'then select max(version)into previous from public.templates where id=p_id;
 else select max(version)into previous from public.readiness_rules;end if;
 if p_version<>coalesce(previous,0)+1 then raise exception 'conflict: next immutable knowledge version required';end if;
 if p_kind='category_profile'then insert into public.category_profiles(id,version,content,review_status,sources)values(p_id,p_version,p_content,status,p_sources);
 elsif p_kind='playbook'then if jsonb_typeof(p_content->'steps')is distinct from'array'or jsonb_array_length(p_content->'steps')=0 or exists(select from jsonb_array_elements(p_content->'steps')step where jsonb_typeof(step)is distinct from'object'or length(coalesce(step->>'id',''))=0 or length(coalesce(step->>'instruction',''))=0 or coalesce(step->>'source','')!~'^https://'or jsonb_typeof(step->'optional')is distinct from'boolean')then raise exception 'validation: sourced typed playbook steps required';end if;insert into public.playbooks(id,version,content,review_status,sources)values(p_id,p_version,p_content,status,p_sources);
 elsif p_kind='template'then if coalesce(p_content->>'providerTemplateId','')=''or coalesce(p_content->>'language','')not in('ar','en')or coalesce(p_content->>'purpose','')=''or coalesce(p_content->>'body','')=''then raise exception 'validation: frozen provider template content required';end if;insert into public.templates(id,version,content,review_status,sources)values(p_id,p_version,p_content,status,p_sources);
 else
  if status<>'reviewed'or jsonb_typeof(p_content->'rules')is distinct from'array'or jsonb_array_length(p_content->'rules')<>30 then raise exception 'needs_approval: a complete human-reviewed readiness ruleset required';end if;
  if exists(select from(select outcome,level from unnest(array['brand','product','supply','commerce','compliance','demand'])outcome cross join generate_series(1,5)level)required where(select count(*)from jsonb_array_elements(p_content->'rules')r where r->>'outcome'=required.outcome and r->>'level'=required.level::text)<>1)then raise exception 'validation: exactly one rule for each outcome and level required';end if;
  for rule in select value from jsonb_array_elements(p_content->'rules')loop if(rule->>'level')::integer>=4 and rule->'highTrust'is distinct from'true'::jsonb then raise exception 'invariant_violation: R4/R5 high-trust evidence cannot be disabled';end if;insert into public.readiness_rules(id,version,outcome,level,evidence_kinds,decision_gates,high_trust,review_status,performed_kinds,founder_kinds,ledger_gate)values(p_id||':'||(rule->>'outcome')||':'||(rule->>'level'),p_version,rule->>'outcome',(rule->>'level')::integer,array(select jsonb_array_elements_text(rule->'evidenceKinds')),array(select jsonb_array_elements_text(rule->'decisionGates')),(rule->>'highTrust')::boolean,'reviewed',array(select jsonb_array_elements_text(coalesce(rule->'performedKinds','[]'))),array(select jsonb_array_elements_text(coalesce(rule->'founderKinds','[]'))),rule->>'ledgerGate');end loop;
 end if;
 insert into public.knowledge_revisions(kind,knowledge_id,version,content_hash,source_hash,sources,review_status,reviewer_reference,review_reference,reviewed_at)values(p_kind,p_id,p_version,hash,source_hash,p_sources,status,reviewer,p_review->>'reviewReference',review_at)returning id into result;return result;
end$$;
create function public.activate_knowledge_version(p_kind text,p_id text,p_version integer)returns void language plpgsql security definer set search_path=''as $$declare reviewer text;begin
 perform private.require_role(array['knowledge_reviewer_role']);select reviewer_reference into strict reviewer from private.knowledge_reviewers where login_role=session_user and enabled;
 if p_kind='readiness_rules'then raise exception 'needs_approval: readiness activation also requires code/SQL parity and evaluation release; append-only staging does not activate rules';end if;
 if not exists(select from public.knowledge_revisions where kind=p_kind and knowledge_id=p_id and version=p_version and review_status='reviewed')then raise exception 'needs_approval: reviewed knowledge revision required';end if;
 insert into public.knowledge_pointers(kind,knowledge_id,version,reviewer_reference)values(p_kind,p_id,p_version,reviewer);
end$$;
create function public.knowledge_active_version(p_kind text,p_id text)returns integer language plpgsql stable security definer set search_path=''as $$declare version integer;begin
 perform private.require_role(array['founder_role','lead_role','specialist_role','policy_role','knowledge_role','knowledge_reviewer_role']);select p.version into version from public.knowledge_pointers p where p.kind=p_kind and p.knowledge_id=p_id order by p.created_at desc,p.id desc limit 1;if version is not null then return version;end if;
 if p_kind='category_profile'then return(select coalesce(max(p.version)filter(where not exists(select from public.knowledge_revisions r where r.kind='category_profile'and r.knowledge_id=p.id and r.version=p.version)),min(p.version))from public.category_profiles p where id=p_id);elsif p_kind='playbook'then return(select coalesce(max(p.version)filter(where not exists(select from public.knowledge_revisions r where r.kind='playbook'and r.knowledge_id=p.id and r.version=p.version)),min(p.version))from public.playbooks p where id=p_id);elsif p_kind='template'then return(select coalesce(max(p.version)filter(where not exists(select from public.knowledge_revisions r where r.kind='template'and r.knowledge_id=p.id and r.version=p.version)),min(p.version))from public.templates p where id=p_id);end if;return null;
end$$;
revoke all on function public.append_knowledge_revision(text,text,integer,jsonb,text[],jsonb),public.activate_knowledge_version(text,text,integer),public.knowledge_active_version(text,text)from public;
grant execute on function public.append_knowledge_revision(text,text,integer,jsonb,text[],jsonb)to knowledge_role,knowledge_reviewer_role;
grant execute on function public.activate_knowledge_version(text,text,integer)to knowledge_reviewer_role;
grant execute on function public.knowledge_active_version(text,text)to founder_role,lead_role,specialist_role,policy_role,knowledge_role,knowledge_reviewer_role;
commit;
